        function e(n) {
            const r = n.regex,
                i = /([2-9]|[1-2]\d|[3][0-5])\^\^/,
                a = /(\w*\.\w+|\w+\.\w*|\w+)/,
                o = /(\d*\.\d+|\d+\.\d*|\d+)/,
                s = r.either(r.concat(i, a), o),
                c = /``[+-]?(\d*\.\d+|\d+\.\d*|\d+)/,
                l = /`([+-]?(\d*\.\d+|\d+\.\d*|\d+))?/,
                u = r.either(c, l),
                d = /\*\^[+-]?\d+/,
                f = { className: 'number', relevance: 0, begin: r.concat(s, r.optional(u), r.optional(d)) },
                _ = /[a-zA-Z$][a-zA-Z0-9$]*/,
                m = new Set(t),
                h = {
                    variants: [
                        {
                            className: 'builtin-symbol',
                            begin: _,
                            'on:begin': (C, R) => {
                                m.has(C[0]) || R.ignoreMatch()
                            }
                        },
                        { className: 'symbol', relevance: 0, begin: _ }
                    ]
                },
                g = { className: 'named-character', begin: /\\\[[$a-zA-Z][$a-zA-Z0-9]+\]/ },
                v = { className: 'operator', relevance: 0, begin: /[+\-*/,;.:@~=><&|_`'^?!%]+/ },
                b = {
                    className: 'pattern',
                    relevance: 0,
                    begin: /([a-zA-Z$][a-zA-Z0-9$]*)?_+([a-zA-Z$][a-zA-Z0-9$]*)?/
                },
                S = { className: 'slot', relevance: 0, begin: /#[a-zA-Z$][a-zA-Z0-9$]*|#+[0-9]?/ },
                T = { className: 'brace', relevance: 0, begin: /[[\](){}]/ },
                O = { className: 'message-name', relevance: 0, begin: r.concat('::', _) }
            return {
                name: 'Mathematica',
                aliases: ['mma', 'wl'],
                classNameAliases: {
                    brace: 'punctuation',
                    pattern: 'type',
                    slot: 'type',
                    symbol: 'variable',
                    'named-character': 'variable',
                    'builtin-symbol': 'built_in',
                    'message-name': 'string'
                },
                contains: [
                    n.COMMENT(/\(\*/, /\*\)/, { contains: ['self'] }),
                    b,
                    S,
                    O,
                    h,
                    g,
                    n.QUOTE_STRING_MODE,
                    f,
                    v,
                    T
                ]
            }
        }
